import{_ as a,o as l,c as r,a2 as o}from"./chunks/framework.CYjxsSA2.js";const c=JSON.parse('{"title":"排障手册","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/troubleshooting.md","filePath":"advanced/troubleshooting.md"}'),i={name:"advanced/troubleshooting.md"};function e(n,t,d,s,h,g){return l(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="排障手册" tabindex="-1">排障手册 <a class="header-anchor" href="#排障手册" aria-label="Permalink to &quot;排障手册&quot;">​</a></h1><p>本章汇总<strong>静默失败高发点</strong>与常见限制。遇到「没报错但结果不对」时，优先来这里对照。</p><h2 id="一、先看这几类静默降级" tabindex="-1">一、先看这几类静默降级 <a class="header-anchor" href="#一、先看这几类静默降级" aria-label="Permalink to &quot;一、先看这几类静默降级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>真正的原因</th><th>处理</th></tr></thead><tbody><tr><td>IP 归属全是「未知」</td><td>缺少 IP 归属离线库</td><td>按<a href="/vaelor/download.html#可选资源">下载与安装</a>的说明补上离线库</td></tr><tr><td>HTTPS 抓包只看到隧道信息、没有明文</td><td>根证书未被信任</td><td>在数据目录中找到抓包根证书并信任它</td></tr><tr><td>命令报「必须隔离执行，但没有可用隔离环境」</td><td>档位为「必须隔离」且容器 / WSL 都未启用</td><td>启用工具箱，或改档位</td></tr><tr><td>浏览器取证不可用</td><td>没找到 Chrome</td><td>安装 Chrome 后重启程序；已安装仍不识别请联系技术支持</td></tr><tr><td>空间测绘某平台报「无凭据」</td><td>该平台 API Key 未配</td><td>系统配置 → 空间测绘，补齐该平台凭据</td></tr></tbody></table><h2 id="二、代理类" tabindex="-1">二、代理类 <a class="header-anchor" href="#二、代理类" aria-label="Permalink to &quot;二、代理类&quot;">​</a></h2><ul><li><strong>配了代理但流量没走代理</strong> —— 启用条件是「开关打开 <strong>且</strong> 链上至少有一个节点」</li><li><strong>只有某个功能不走代理</strong> —— 检查<strong>代理路由</strong>里该功能域的出口设置</li><li><strong>容器检测判定为不可用</strong> —— 检测超时很短，Docker 卡顿时会被误判为不可用，稍后重试</li></ul><h2 id="三、扫描与测绘" tabindex="-1">三、扫描与测绘 <a class="header-anchor" href="#三、扫描与测绘" aria-label="Permalink to &quot;三、扫描与测绘&quot;">​</a></h2><ul><li>空间扫描单次目标数有上限，超出请拆分网段</li><li>攻击面清单看起来不全 —— 超大站点的 sitemap 与表单会被截断，属保护性限制</li><li>续扫后深层页面丢失 —— 未完成的队列不会保留，无法从入口页重新发现的深层页面不会恢复</li><li>ICMP 探测很慢 —— 缺少管理员权限时回落系统 <code>ping</code></li><li>界面刷新看起来「卡顿」 —— 进度事件有节流，属正常现象</li></ul><h2 id="四、空间测绘" tabindex="-1">四、空间测绘 <a class="header-anchor" href="#四、空间测绘" aria-label="Permalink to &quot;四、空间测绘&quot;">​</a></h2><ul><li>FOFA 返回「没有权限搜索 X 字段」 —— 低等级账号请求了高等级字段，平台会自动降档重试</li><li>域名 / IP 模式查询内容不能为空</li><li>每页条数受各家 API 约束</li></ul><h2 id="五、大模型与军团" tabindex="-1">五、大模型与军团 <a class="header-anchor" href="#五、大模型与军团" aria-label="Permalink to &quot;五、大模型与军团&quot;">​</a></h2><ul><li><strong>模型不调用工具</strong> —— 确认模型支持 Tool Use、角色工具开关已启用、Provider 连通</li><li><strong>连接失败</strong> —— 先调大模型请求超时与流式空闲超时</li><li><strong>模型名大小写敏感</strong> —— 必须与中转站控制台完全一致</li><li><strong>权限被降档</strong> —— 「完全访问」不持久化，重开程序会回落，点顶部提示可改回</li></ul><h2 id="六、漏洞管理" tabindex="-1">六、漏洞管理 <a class="header-anchor" href="#六、漏洞管理" aria-label="Permalink to &quot;六、漏洞管理&quot;">​</a></h2><ul><li><strong>发现列表是空的，但会话里有结论</strong> —— 只有入账的发现才出现在这里</li><li><strong>严重度与报告里写的不一致</strong> —— 账本严重度只升不降，重复登记取最重的一次</li><li><strong>某条发现写着「证据来自历史运行」</strong> —— 该证据取自更早的运行，不计入本次战果</li><li><strong>侦察报告导不出</strong> —— 侦察仍在进行时不允许导出，完成后再试</li></ul><h2 id="七、数据与实例" tabindex="-1">七、数据与实例 <a class="header-anchor" href="#七、数据与实例" aria-label="Permalink to &quot;七、数据与实例&quot;">​</a></h2><ul><li><strong>找不到数据</strong> —— 数据在数据目录，或你另行指定的位置（见<a href="/vaelor/download.html#数据目录">下载与安装</a>）</li><li><strong>启动被拒「数据目录已被另一个进程占用」</strong> —— 关掉另一个实例；并行跑必须用不同数据目录</li><li><strong>数据库被锁定</strong> —— 确保没有其他实例在运行；仍不行则重启</li></ul><h2 id="八、平台差异" tabindex="-1">八、平台差异 <a class="header-anchor" href="#八、平台差异" aria-label="Permalink to &quot;八、平台差异&quot;">​</a></h2><ul><li><strong>WSL 工具箱</strong>仅 Windows</li><li><strong>数据目录位置</strong> —— Windows 为程序所在目录，macOS 为系统的应用数据目录</li></ul><h2 id="九、仍然解决不了" tabindex="-1">九、仍然解决不了 <a class="header-anchor" href="#九、仍然解决不了" aria-label="Permalink to &quot;九、仍然解决不了&quot;">​</a></h2><p>收集以下信息联系 Gh0xE9：</p><ol><li>版本号（关于页）与平台</li><li>数据目录路径</li><li>复现步骤与具体报错文案</li><li>相关模块的日志</li></ol>',21)])])}const b=a(i,[["render",e]]);export{c as __pageData,b as default};
